  exists (irr + 1). unfold art_credit_ok. cbn [art_gs_malloc g_log g_sec g_sec_committed g_depot g_cls g_qt g_qg fst snd length].
  rewrite Nat2Z.inj_succ, Edep in *. rewrite Nat2Z.inj_succ in C9.
