Theorem art_alloc_rep_frame_sh : forall FSG MAPS0 RESV0 rn G LB (M M' : word -> option byte) b0 c0,
  art_alloc_rep FSG rn G LB M -> mem_grows M M' ->
  (forall x : word, art_alloc_zone FSG rn G (U x) -> ~ in_block LB (U x) -> ~ in_shadow_of b0 c0 (U x) -> M' x = M x) ->
  cellA M' (rn_tp rn + rn_loff rn) 4 0 -> live_ok MAPS0 RESV0 (rn_HI rn) (art_live (g_log FSG G)) -> art_kn_ok MAPS0 RESV0 rn ->
  In (b0, c0) LB -> b0 mod 16 = 0 -> 0 < c0 -> HAJ.shadow_blkR M' b0 c0 ->
